            "text": "التفكير الناقد للفصل الأول (صفحة 23):\n\nس1: هل يمكن لجسم أن يتحرك وتكون إزاحته الكلية صفراً؟ وضح ذلك مع مثال.\nج1: نعم، عندما يبدأ الجسم حركته من نقطة معينة ثم يعود في نهاية مساره إلى نفس نقطة البداية، كعداء يدور حول مضمار دائري دورة كاملة ويعود لخط البداية، فتكون إزاحته صفراً ومسافته مساوية لمحيط المضمار.\n\nس2: نشاط تمهيدي لقوانين الحركة (القصور الذاتي):\n- ضع قدحاً فوق طاولة، وضع فوق فوهته بطاقة ورقية، وضع قطعة نقود معدنية فوق البطاقة.\n- عند سحب البطاقة ببطء تتحرك قطعة النقود معها.\n- لكن عند نقر البطاقة بسرعة خاطفة، تطير البطاقة وتسقط قطعة النقود داخل القدح بسبب خاصية (القصور الذاتي) ومقاومتها للتغير المفاجئ في حالتها الساكنة.",
