                    "q": "س1 تفكير ناقد: هل يمكن لجسم أن يتحرك وتكون إزاحته الكلية صفراً؟ وضح ذلك مع ذكر مثال عملي دقيق.",
                    "a": "✅ نعم، يمكن ذلك بالتأكيد.\n\nالتوضيح العلمي:\nتكون الإزاحة الكلية صفراً عندما يعود الجسم المتحرك في نهاية مساره إلى نقطة البداية التي انطلق منها، لأن الإزاحة هي أقصر مسار مستقيم بين البداية والنهاية (Δx = x₂ - x₁ = 0).\n\nالمثال العملي:\nعداء يركض حول مضمار سباق دائري دورة كاملة ويعود إلى خط البداية؛ تكون مسافته المقطوعة مساوية لمحيط المضمار كاملاً (d > 0)، بينما إزاحته الكلية تساوي صفراً تماماً (Δx = 0)."
