          {
            "id": 70208,
            "page": 31,
            "heading": "الفيزياء والتكنولوجيا: مدارات الأقمار الصناعية واستكشاف الفضاء (صفحة 31)",
            "text": "الفيزياء والتكنولوجيا: حركة الأقمار الصناعية\nالقمر الصناعي يدور في مدار دائري حول الأرض بتأثير قوة الجاذبية الأرضية التي تعمل بمثابة (قوة مركزية) تجذبه باستمرار نحو مركز الأرض وتمنعه من الانطلاق في الفضاء بخط مستقيم.\n\nالسرعة المدارية للقمر الصناعي:\nيحتاج القمر الصناعي إلى سرعة محددة تسمى (السرعة المدارية)، فإذا قلت هذه السرعة سقط القمر نحو الأرض واحترق بالغلاف الجوي، وإذا زادت عن حد معين أفلت من جاذبية الأرض وانطلق في أعماق الفضاء الخارجي.\n\nاستخدامات الأقمار الصناعية:\n1. الاتصالات والبث التلفزيوني والإنترنت عبر الأقمار الثابتة المدار.\n2. الأرصاد الجوية ورصد العواصف والأعاصير والتغير المناخي.\n3. الملاحة وتحديد المواقع بواسطة أقمار GPS.\n4. الاستشعار عن بعد والمسح الجغرافي والبحوث الفلكية."
          }
