            "text": "مسائل الفصل الثالث الحسابية (صفحة 44):\n\nمسألة 1: رافعة ترفع حمولة وزنها 2000 N رأسياً إلى ارتفاع 10 m خلال 20 s، احسب:\nأ) الشغل الذي تنجزه الرافعة.\nب) قدرة الرافعة بوحدة الواط.\nالحل:\nأ) W = F · x = 2000 N × 10 m = 20,000 J.\nب) P = W / t = 20,000 J / 20 s = 1,000 W (أو 1 kW).\n\nمسألة 2: كرة كتلتها 0.5 kg تسقط من ارتفاع 4 m عن سطح الأرض (اعتبر g = 10 m/s²). احسب طاقتها الكامنة في أعلى نقطة؟\nالحل:\nPE = m · g · h\nPE = 0.5 kg × 10 m/s² × 4 m = 20 J.",
