            "text": "الفيزياء والمجتمع: الآلات المركبة\nالآلة المركبة (Compound Machine) عبارة عن تجميع لآلتين بسيطتين أو أكثر تعمل معاً بتناغم لأداء مهام شاقة.\nأمثلة وتطبيقات:\n1. الدراجة الهوائية: تدمج بين العجلة والمحور، التروس والعتلات، والفرامل.\n2. الروافع البرجية والكرينات: تعتمد على أنظمة بكرات مركبة متعددة وسطوح مائلة لنقل ورفع أطنان الحديد ومواد البناء الشاهقة بأقل جهد ممكن.\n3. المصاعد الكهربائية: تعتمد على بكرات ميكانيكية وأوزان موازنة لتحقيق حركة آمنة وكفاءة عالية للطاقة."
