                    "a": "📌 المعطيات:\n- الكتلة: m = 200 kg\n- التعجيل: g = 10 N/kg\n- وزن الجسم (المقاومة F₂): F₂ = m · g = 200 × 10 = 2000 N\n- القوة المؤثرة: F₁ = نصف الوزن = ½ × 2000 = 1000 N\n\n• نوع البكرة: بكرة متحركة (لأنها وفرت نصف القوة المبذولة).\n\n• الفائدة الميكانيكية:\n📐 MA = F₂ / F₁\n🔢 MA = 2000 N / 1000 N = 2\n\n🎯 الناتج النهائي: نوع البكرة: متحركة، وفائدتها الميكانيكية = 2 (ربح قوة)."
