                    "a": "📌 المعطيات:\n- العتلة من النوع الثاني (المرتكز في طرف).\n- المقاومة (الثقل): F₂ = 60 N\n- ذراع المقاومة: d₂ = 20 cm\n- ذراع القوة (طول العتلة للطرف الآخر): d₁ = 80 cm\n\n📐 قانون العتلات:\nF₁ × d₁ = F₂ × d₂\n\n🔢 الخطوات والتعويض:\nF₁ × 80 = 60 × 20\nF₁ × 80 = 1200\nF₁ = 1200 / 80 = 15 N\n\nحساب الفائدة الميكانيكية:\n📐 MA = F₂ / F₁\n🔢 MA = 60 N / 15 N = 4 (ربح قوة بمقدار 4 أضعاف).\n\n🎯 الناتج النهائي: القوة المطلوبة = 15 نيوتن (15 N)، والفائدة الميكانيكية = 4."
