                    "q": "أ- احسب سرعة الصوت آنذاك:",
                    "a": "📌 المعطيات:\n- بعد الحاجز: d = 340 m\n- زمن سماع الصوت (الذهاب والإياب في الصدى): t = 2 s\n\n📐 قانون الصدى:\nالمسافة الكلية للذهاب والإياب = 2 × d\nالسرعة v = (2 · d) / t\n\n🔢 الخطوات والتعويض:\nv = (2 × 340 m) / 2 s = 680 / 2 = 340 m/s.\n\n🎯 الناتج: سرعة الصوت آنذاك = 340 متر/ثانية (340 m/s)."
