                    "a": "ينكسر الشعاع مبتعداً عن العمود المقام على السطح الفاصل، وتكون زاوية الانكسار أكبر من زاوية السقوط. وإذا كانت زاوية السقوط أكبر من الزاوية الحرجة يعاني الشعاع انعكاساً كلياً داخلياً في نفس الوسط."
