                    "a": "بسبب ظاهرة (السراب الصحراوي) الناتجة عن الانعكاس الكلي الداخلي لأشعة الضوء في طبقات الهواء الملامسة للأرض شديدة الحرارة والأقل كثافة ضوئية، فتنحني الأشعة للأعلى وتصل لعين السائق فيرى صورة مقلوبة كأنها منعكسة على بركة ماء خادعة."
