    "details": "1. الانطلاق: s = d / t (المسافة على الزمن، كمية مقدارية).\n2. معدل الانطلاق: s_avg = d_total / t_total.\n3. السرعة: v = x / t (الإزاحة على الزمن، كمية اتجاهية)، وتقسم إلى منتظمة وغير منتظمة.\n4. التعجيل: a = Δv / t = (v_final - v_initial) / t بوحدة (m/s²).\n- تعجيل تسارعي (+) عندما تتزايد السرعة.\n- تعجيل تباطؤي (-) عندما تتناقص السرعة."
