    "details": "1. القصور الذاتي: ممانعة الجسم لأي تغيير في حالته الحركية.\n2. كتلة الجسم هي المقياس الحقيقي لقصوره الذاتي، فزيادة الكتلة تزيد القصور وصعوبة التحريك والإيقاف.\n3. التطبيقات العملية: اندفاع الركاب للأمام عند توقف الحافلة المفاجئ، وأهمية حزام الأمان لتثبيت الركاب وتفادي الارتطام."
