    "details": "1. قانون الجذب العام: F = G · (m₁ · m₂) / r².\n2. وزن الجسم: w = m · g (حيث g تعجيل الجاذبية = 9.8 m/s² على الأرض، و1.62 m/s² على القمر).\n3. الكتلة ثابتة في أي مكان بينما الوزن يتغير بتغير الجاذبية.\n4. السقوط الحر: حركة الأجسام بتأثير الجاذبية الأرضية فقط بإهمال مقاومة الهواء، وتسقط جميع الكتل بنفس التعجيل وتصل معاً في الفراغ."
