    "details": "1. الطاقة الحركية: KE = ½ · m · v² (تتناسب طردياً مع الكتلة ومربع السرعة v²).\n2. الطاقة الكامنة التثاقلية: PE = m · g · h (تعتمد على الكتلة والارتفاع الرأسي).\n3. قانون حفظ الطاقة: الطاقة لا تفنى ولا تستحدث من العدم بل تتحول من شكل لآخر، ومجموع الطاقة الكلية في النظام المغلق ثابت."
