    "details": "1. قانون العتلات: القوة × ذراعها = المقاومة × ذراعها (F₁ · d₁ = F₂ · d₂).\n2. الفائدة الميكانيكية: MA = المقاومة / القوة = F₂ / F₁ = d₁ / d₂.\n- MA > 1: ربح قوة (d₁ > d₂).\n- MA < 1: ربح سرعة (d₂ > d₁).\n3. الأنواع الثلاثة:\n- النوع 1: المرتكز في الوسط (المقص والميزان).\n- النوع 2: المقاومة في الوسط وربح قوة دائماً (عربة الحديقة).\n- النوع 3: القوة في الوسط وربح سرعة دائماً (الملقط والمكنسة)."
