        "answer": "<strong>الجواب النموذجي (20 درجة):</strong><br><strong>أ) المقارنة بين المسافة والإزاحة (10 درجات):</strong><br>• <strong>المسافة (d):</strong> طول المسار الفعلي الذي يسلكه الجسم للانتقال من نقطة لأخرى، كمية مقدارية (قياسية)، تقاس بالمتر (m).<br>• <strong>الإزاحة (x):</strong> أقصر مسار مستقيم متجه من نقطة البداية إلى نقطة النهاية، كمية اتجاهية متجهة، تقاس بالمتر (m).<br><br><strong>ب) قيم البادئات الأسية (10 درجات - درجتان لكل بادئة):</strong><br>1. الميجا (M) = <span dir='ltr' class='phy-formula'>10⁶</span>.<br>2. الكيلو (k) = <span dir='ltr' class='phy-formula'>10³</span>.<br>3. السنتي (c) = <span dir='ltr' class='phy-formula'>10⁻²</span>.<br>4. الملي (m) = <span dir='ltr' class='phy-formula'>10⁻³</span>.<br>5. النانو (n) = <span dir='ltr' class='phy-formula'>10⁻⁹</span>."
