        "content": "<p><strong>أ) ضع كلمة (صح) أو (خطأ) أمام العبارات الآتية مع تصحيح الخطأ إن وجد (10 درجات):</strong></p><ol><li>كتلة الجسم على سطح الأرض تختلف عن كتلته على سطح القمر.</li><li>الجول الواحد يكافئ حاصل ضرب نيوتن في متر (<span dir='ltr' class='phy-formula'>1 J = 1 N · m</span>).</li><li>التعجيل التباطؤي يكون فيه اتجاه التعجيل بنفس اتجاه السرعة.</li><li>قانون الجذب العام لنيوتن ينص على أن قوة التجاذب بين كتلتين تتناسب طردياً مع مربع البعد بينهما.</li><li>القدرة الحصانية الواحدة تعادل <span dir='ltr' class='phy-formula'>746 W</span>.</li></ol><p><strong>ب) اختر الجواب الصحيح من بين الأقواس (10 درجات):</strong></p><ol><li>حركة بندول الساعة تمثل حركة: (انتقالية / <strong>دورية اهتزازية</strong> / عشوائية).</li><li>إذا تضاعفت سرعة جسم متحرك فإن طاقته الحركية: (تتضاعف مرتين / <strong>تتضاعف 4 مرات</strong> / لا تتغير).</li></ol>",
