        "answer": "<strong>الجواب النموذجي (20 درجة):</strong><br><strong>أ) حل محصلة الإزاحتين:</strong><br>بما أن الشرق والشمال متعامدان:<br><div dir='ltr' class='phy-math-block'>x<sub>R</sub> = √(x₁² + x₂²) = √(6² + 8²) = √(36 + 64) = √(100) = 10 m</div> باتجاه شمال الشرق.<br><strong>ب) حل مسألة التعجيل:</strong><br>السرعة الابتدائية <span dir='ltr' class='phy-formula'>v<sub>i</sub> = 24 m/s</span>، والسرعة النهائية <span dir='ltr' class='phy-formula'>v<sub>f</sub> = 0</span> (توقفت تماماً)، والزمن <span dir='ltr' class='phy-formula'>t = 4 s</span>.<br><div dir='ltr' class='phy-math-block'>a = (v<sub>f</sub> - v<sub>i</sub> / t) = (0 - 24 / 4) = -6 m/s²</div><br>التعجيل مقداره <span dir='ltr' class='phy-formula'>6 m/s²</span> ونوعه <strong>تعجيل تباطؤي</strong> سالب لأن السرعة تناقصت."
